import { FOODS, REGIONS, MEALS, ADDONS, EXERCISES, DEFAULT_GOALS } from './data.js';
import { STATIC_PREVIEW } from './deployment.js';
import { welcomeMarkup } from './welcome.js';
import { CloudSync, accountMarkup } from './cloud.js';
import { scaledNutrition, sumNutrition, ratio, round, exerciseCalories, isoLocal, shiftDay, weekDates, niceDate } from './nutrition.js';
import { loadState, saveState, clearState, importState, uid } from './store.js';
import {toolsPage} from './advanced-ui.js';
import {MICRO_DEFINITIONS,parseMicros,scaleMicros,recipeMicros} from './micro.js';
import {ensureV3,createMealTemplate,applyMealTemplate,bulkDiaryChange,readRecipeLines,recipeNutrition,calculateEnergyNeeds,setDietPreset,createCorrection,importHealthCsv} from './v3.js';
import {ensureExtensions, goalsForDay, applyRepeatsForDay, copyPreviousDay, dayKey, activeFast, matchFoodQuery, BIOMETRICS} from './advanced.js';
let state = ensureV3(ensureExtensions(loadState()));
const cloud = new CloudSync({replaceLocal(next){state=ensureV3(ensureExtensions(next));render();},readLocal(){return state;},onChange(){if(ui?.page==='settings')render();}});
const ui={page:'home',day:isoLocal(),region:'All',query:'',favoritesOnly:false,modal:null,foodId:null,entryId:null,meal:'Lunch',grams:250,addons:[],recipeIngredients:[],recipeFood:'jollof',recipeGrams:100,insights:'week',toast:'',toolsTab:'plan',selectedWeekDay:1,chartMetric:'kcal',chartDays:7,oracleField:'protein',smartText:''};
if(!state.preferences?.onboarded&&!state.diary.length&&!state.customFoods.length)ui.page='welcome';
ui.v3ChartA='kcal';ui.v3ChartB='steps';ui.v3ChartDays=14;
const app=document.getElementById('app');
let cameraScanStream=null,cameraScanToken=0;
